"""
pyexcel_xlsx.interfaces
~~~~~~~~~~~~~~~~~~~~~~~~

Shared interfaces to decouple xlsx implementation details

:copyright: (c) 2015-2025 by Onni Software Ltd & its contributors
:license: New BSD License
"""


class IDataSource:
    """Interface for data sources (readers)"""
    def read_sheet(self, sheet_index):
        """Return a sheet object for the given sheet index"""
        raise NotImplementedError

    def close(self):
        """Close the data source"""
        raise NotImplementedError


class IDataSink:
    """Interface for data sinks (writers)"""
    def create_sheet(self, name):
        """Create a new sheet and return a sheet writer"""
        raise NotImplementedError

    def close(self):
        """Flush and close the data sink"""
        raise NotImplementedError


class ISheet:
    """Interface for a worksheet"""
    def row_iterator(self):
        """Return an iterator over rows"""
        raise NotImplementedError

    def column_iterator(self, row):
        """Return an iterator over columns in the given row"""
        raise NotImplementedError


class ISheetWriter:
    """Interface for a sheet writer"""
    def write_row(self, array):
        """Write a row of data"""
        raise NotImplementedError

    def close(self):
        """Close the sheet writer"""
        raise NotImplementedError
